export default JSON.parse(
  "{\n  \"workId\": \"xunzi\",\n  \"chapter\": {\n    \"id\": \"xunzi_ch-11\",\n    \"workId\": \"xunzi\",\n    \"order\": 11,\n    \"title\": \"王霸\",\n    \"difficulty\": 4,\n    \"estimatedMinutes\": 19,\n    \"passageIds\": [\n      \"xunzi_ch-11_p-1\",\n      \"xunzi_ch-11_p-2\",\n      \"xunzi_ch-11_p-3\",\n      \"xunzi_ch-11_p-4\",\n      \"xunzi_ch-11_p-5\",\n      \"xunzi_ch-11_p-6\",\n      \"xunzi_ch-11_p-7\",\n      \"xunzi_ch-11_p-8\",\n      \"xunzi_ch-11_p-9\",\n      \"xunzi_ch-11_p-10\",\n      \"xunzi_ch-11_p-11\",\n      \"xunzi_ch-11_p-12\",\n      \"xunzi_ch-11_p-13\",\n      \"xunzi_ch-11_p-14\",\n      \"xunzi_ch-11_p-15\",\n      \"xunzi_ch-11_p-16\",\n      \"xunzi_ch-11_p-17\",\n      \"xunzi_ch-11_p-18\",\n      \"xunzi_ch-11_p-19\",\n      \"xunzi_ch-11_p-20\"\n    ],\n    \"tags\": [\n      \"儒家\",\n      \"性惡論\",\n      \"禮樂\"\n    ]\n  },\n  \"passages\": [\n    {\n      \"id\": \"xunzi_ch-11_p-1\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 1,\n      \"canonicalText\": \"國者，天下之制，利用也；人主者，天下之利埶也。得道以持之，則大安也，大榮也，積美之源也；不得道以持之，則大危也，大累也，有之不如無之；及其綦也，索為匹夫不可得也，齊湣、宋獻是也。故人主天下之利埶也，然而不能自安也，安之者必將道也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-1_s-1\",\n        \"xunzi_ch-11_p-1_s-2\",\n        \"xunzi_ch-11_p-1_s-3\",\n        \"xunzi_ch-11_p-1_s-4\",\n        \"xunzi_ch-11_p-1_s-5\",\n        \"xunzi_ch-11_p-1_s-6\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"國的人或事，天下的制，利用啊；人主的人或事，天下的利埶啊。得道以持的，則大安啊，大榮啊，積美的源啊；不得道以持的，則大危啊，大累啊，有的不如無的；及他的綦啊，索為匹夫不可得啊，齊湣、宋獻是啊。所以人主天下的利埶啊，然而且不能自安啊，安的的人或事必將道啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「國者，天下之制，利用也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「國」、「天」、「下」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「國者天下之制利用也人主者天下之利埶也得道以持之則」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「人主者，天下之利埶也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 2,\n      \"canonicalText\": \"故用國者，義立而王，信立而霸，權謀立而亡。三者明主之所謹擇也，仁人之所務白也。絜國以呼禮義，而無以害之，行一不義，殺一無罪，而得天下，仁者不為也。擽然扶持心國，且若是其固也。所與為之者，之人則舉義士也；所以為布陳於國家刑法者，則舉義法也；主之所極然帥群臣而首鄉之者，則舉義志也。如是則下仰上以義矣，是綦定也；綦定而國定，國定而天下定。仲尼無置錐之地，誠義乎志意，加義乎身行，箸之言語，濟之日，不隱乎天下，名垂乎後世。今亦以天下之顯諸侯，誠義乎志意，加義乎法則度量，箸之以政事，案申重之以貴賤殺生，使襲然終始猶一也。如是，則夫名聲之部發於天地之間也，豈不如日月雷霆然矣哉！故曰：以國齊義，一日而白，湯武是也。湯以亳，武王以鄗，皆百里之地也，天下為一，諸侯為臣，通達之屬，莫不從服，無它故焉，以義濟矣。是所謂義立而王也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-2_s-1\",\n        \"xunzi_ch-11_p-2_s-2\",\n        \"xunzi_ch-11_p-2_s-3\",\n        \"xunzi_ch-11_p-2_s-4\",\n        \"xunzi_ch-11_p-2_s-5\",\n        \"xunzi_ch-11_p-2_s-6\",\n        \"xunzi_ch-11_p-2_s-7\",\n        \"xunzi_ch-11_p-2_s-8\",\n        \"xunzi_ch-11_p-2_s-9\",\n        \"xunzi_ch-11_p-2_s-10\",\n        \"xunzi_ch-11_p-2_s-11\",\n        \"xunzi_ch-11_p-2_s-12\",\n        \"xunzi_ch-11_p-2_s-13\",\n        \"xunzi_ch-11_p-2_s-14\",\n        \"xunzi_ch-11_p-2_s-15\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以用國的人或事，道義正道立而且王，信立而且霸，權謀立而且亡。三的人或事明主的所謹擇啊，仁愛之德人的所務白啊。絜國以呼禮道義正道道德行修養規程道義正道，而且無以害的，行一不道義正道，殺一無罪，而且得天下，仁愛之德的人或事不為啊。擽然扶持心國，且若是他的固啊。所與為的的人或事，的人則舉道義正道士啊；所以為布陳於國家刑典章法度的人或事，則舉道義正道典章法度啊；主的所極然帥群臣而且首鄉的的人或事，則舉道義正道志啊。如是則下仰上以道義正道矣，是綦定啊；綦定而且國定，國定而且天下定。仲尼無置錐的地，誠道義正道乎志意，加道義正道乎身行，箸的言語，濟的日，不隱乎天下，名垂乎後世。今亦以天下的顯諸侯，誠道義正道乎志意，加道義正道乎典章法度則度量，箸的以政事，案申重的以貴賤殺生，使襲然終始猶一啊。如是，則夫名聲的部發於天地的間啊，豈不如日月雷霆然矣哉！所以說：以國齊道義正道，一日而且白，湯武是啊。湯以亳，武王以鄗，皆百里的地啊，天下為一，諸侯為臣，通達的屬，莫不從服，無它所以焉，以道義正道濟矣。是所謂道義正道立而且王啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「故用國者，義立而王，信立而霸，權謀立而亡」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「用」、「國」、「義」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故用國者義立而王信立而霸權謀立而亡三者明主之所謹」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「三者明主之所謹擇也，仁人之所務白也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 3,\n      \"canonicalText\": \"德雖未至也，義雖未濟也，然而天下之理略奏矣，刑賞已諾信乎天下矣，臣下曉然皆知其可要也。政令已陳，雖睹利敗，不欺其民；約結已定，雖睹利敗，不欺其與。如是，則兵勁城固，敵國畏之；國一綦明，與國信之；雖在僻陋之國，威動天下，五伯是也。非本政教也，非致隆高也，非綦文理也，非服人之心也，鄉方略，審勞佚，謹畜積，脩戰備，齺然上下相信，而天下莫之敢當。故齊桓、晉文、楚莊、吳闔閭、越勾踐，是皆僻陋之國也，威動天下，彊殆中國，無它故焉，略信也。是所謂信立而霸也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-3_s-1\",\n        \"xunzi_ch-11_p-3_s-2\",\n        \"xunzi_ch-11_p-3_s-3\",\n        \"xunzi_ch-11_p-3_s-4\",\n        \"xunzi_ch-11_p-3_s-5\",\n        \"xunzi_ch-11_p-3_s-6\",\n        \"xunzi_ch-11_p-3_s-7\",\n        \"xunzi_ch-11_p-3_s-8\",\n        \"xunzi_ch-11_p-3_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"品德修養雖未至啊，正義道義雖未濟啊，然而且天下的理略奏矣，刑賞已諾信乎天下矣，臣下曉然皆知他的可要啊。政令已陳，雖睹利敗，不欺他的民；約結已定，雖睹利敗，不欺他的與。如是，則兵勁城固，敵國畏的；國一綦明，與國信的；雖在僻陋的國，威動天下，五伯是啊。絕不是本政教啊，絕不是致隆高啊，絕不是綦文理啊，絕不是服人的心啊，鄉方略，審勞佚，謹畜積，脩戰備，齺然上下相信，而且天下莫的敢當。所以齊桓、晉文、楚莊、吳闔閭、越勾踐，是皆僻陋的國啊，威動天下，彊殆中國，無它所以焉，略信啊。是所謂信立而且霸啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「德雖未至也，義雖未濟也，然而天下之理略奏矣，刑賞已諾信乎天下矣，臣下曉然皆知其可要也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「德」、「未」、「至」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「德雖未至也義雖未濟也然而天下之理略奏矣刑賞已諾信」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「政令已陳，雖睹利敗，不欺其民」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 4,\n      \"canonicalText\": \"絜國以呼功利，不務張其義，齊其信，唯利之求，內則不憚詐其民，而求小利焉；外則不憚詐其與，而求大利焉，內不脩正其所以有，然常欲人之有。如是，則臣下百姓莫不以詐心待其上矣。上詐其下，下詐其上，則是上下析也。如是，則敵國輕之，與國疑之，權謀日行，而國不免危削，綦之而亡，齊閔、薛公是也。故用彊齊，非以修禮義也，非以本政教也，非以一天下也，綿綿常以結引馳外為務。故彊、南足以破楚，西足以詘秦，北足以敗燕，中足以舉宋。及以燕趙起而攻之，若振槁然，而身死國亡，為天下大戮，後世言惡，則必稽焉。是無它故焉，唯其不由禮義，而由權謀也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-4_s-1\",\n        \"xunzi_ch-11_p-4_s-2\",\n        \"xunzi_ch-11_p-4_s-3\",\n        \"xunzi_ch-11_p-4_s-4\",\n        \"xunzi_ch-11_p-4_s-5\",\n        \"xunzi_ch-11_p-4_s-6\",\n        \"xunzi_ch-11_p-4_s-7\",\n        \"xunzi_ch-11_p-4_s-8\",\n        \"xunzi_ch-11_p-4_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"絜國以呼功利，不務張他的正義道義，齊他的信，唯利的求，內則不憚詐他的民，而且求小利焉；外則不憚詐他的與，而且求大利焉，內不脩正他的所以有，然常欲人的有。如是，則臣下百姓莫不以詐心待他的上矣。上詐他的下，下詐他的上，則是上下析啊。如是，則敵國輕的，與國疑的，權謀日行，而且國不免危削，綦的而且亡，齊閔、薛公是啊。所以用彊齊，絕不是以修禮正義道義道品德修養規程正義道義啊，絕不是以本政教啊，絕不是以一天下啊，綿綿常以結引馳外為務。所以彊、南足以破楚，西足以詘秦，北足以敗燕，中足以舉宋。及以燕趙起而且攻的，若振槁然，而且身死國亡，為天下大戮，後世言惡，則必稽焉。是無它所以焉，唯他的不由禮正義道義道品德修養規程正義道義，而且由權謀啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「絜國以呼功利，不務張其義，齊其信，唯利之求，內則不憚詐其民，而求小利焉」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「絜」、「國」、「呼」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「絜國以呼功利不務張其義齊其信唯利之求內則不憚詐其」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「外則不憚詐其與，而求大利焉，內不脩正其所以有，然常欲人之有」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-5\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 5,\n      \"canonicalText\": \"三者明主之所以謹擇也，而仁人之所以務白也。善擇者制人，不善擇者人制之。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-5_s-1\",\n        \"xunzi_ch-11_p-5_s-2\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"三的人或事明主的所以謹擇啊，而且仁愛之德人的所以務白啊。善擇的人或事制人，不善擇的人或事人制的。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「三者明主之所以謹擇也，而仁人之所以務白也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「三」、「明」、「主」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「三者明主之所以謹擇也而仁人之所以務白也善擇者制人」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「善擇者制人，不善擇者人制之」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 6,\n      \"canonicalText\": \"國者、天下之大器也，重任也，不可不善為擇所而後錯之，錯險則危；不可不善為擇道然後道之，塗薉則塞；危塞則亡。彼國錯者，非封焉之謂也，何法之道，誰子之與也。故道王者之法，與王者之人為之，則亦王；道霸者之法，與霸者之人為之，則亦霸；道亡國之法，與亡國之人為之，則亦亡。三者明主之所以謹擇也，而仁人之所以務白也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-6_s-1\",\n        \"xunzi_ch-11_p-6_s-2\",\n        \"xunzi_ch-11_p-6_s-3\",\n        \"xunzi_ch-11_p-6_s-4\",\n        \"xunzi_ch-11_p-6_s-5\",\n        \"xunzi_ch-11_p-6_s-6\",\n        \"xunzi_ch-11_p-6_s-7\",\n        \"xunzi_ch-11_p-6_s-8\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"國的人或事、天下的大器啊，重任啊，不可不善為擇所而且後錯的，錯險則危；不可不善為擇道然後道的，塗薉則塞；危塞則亡。彼國錯的人或事，絕不是封焉的謂啊，何典章法度的道，誰子的與啊。所以道王的人或事的典章法度，與王的人或事的人為的，則亦王；道霸的人或事的典章法度，與霸的人或事的人為的，則亦霸；道亡國的典章法度，與亡國的人為的，則亦亡。三的人或事明主的所以謹擇啊，而且仁愛之德人的所以務白啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「國者、天下之大器也，重任也，不可不善為擇所而後錯之，錯險則危」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「國」、「天」、「下」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「國者天下之大器也重任也不可不善為擇所而後錯之錯險」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「不可不善為擇道然後道之，塗薉則塞」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 7,\n      \"canonicalText\": \"故國者、重任也，不以積持之則不立。故國者，世所以新者也，是憚，憚、非變也，改王改行也。故一朝之日也，一日之人也，然而厭焉有千歲之國，何也？曰：援夫千歲之信法以持之也，安與夫千歲之信士為之也。人無百歲之壽，而有千歲之信士，何也？曰：以夫千歲之法自持者，是乃千歲之信士矣。故與積禮義之君子為之則王，與端誠信全之士為之則霸，與權謀傾覆之人為之則亡。三者明主之所以謹擇也，仁人之所以務白也。善擇之者制人，不善擇之者人制之。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-7_s-1\",\n        \"xunzi_ch-11_p-7_s-2\",\n        \"xunzi_ch-11_p-7_s-3\",\n        \"xunzi_ch-11_p-7_s-4\",\n        \"xunzi_ch-11_p-7_s-5\",\n        \"xunzi_ch-11_p-7_s-6\",\n        \"xunzi_ch-11_p-7_s-7\",\n        \"xunzi_ch-11_p-7_s-8\",\n        \"xunzi_ch-11_p-7_s-9\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"所以國的人或事、重任啊，不以積持的則不立。所以國的人或事，世所以新的人或事啊，是憚，憚、絕不是變啊，改王改行啊。所以一朝的日啊，一日的人啊，然而且厭焉有千歲的國，何啊？說道：援夫千歲的信典章法度以持的啊，安與夫千歲的信士為的啊。人無百歲的壽，而且有千歲的信士，何啊？說道：以夫千歲的典章法度自持的人或事，是乃千歲的信士矣。所以與積禮道義正道道德行修養規程道義正道的君子為的則王，與端誠信全的士為的則霸，與權謀傾覆的人為的則亡。三的人或事明主的所以謹擇啊，仁愛之德人的所以務白啊。善擇的的人或事制人，不善擇的的人或事人制的。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「故國者、重任也，不以積持之則不立」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「國」、「重」、「任」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「故國者重任也不以積持之則不立故國者世所以新者也是」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「故國者，世所以新者也，是憚，憚、非變也，改王改行也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 8,\n      \"canonicalText\": \"彼持國者，必不可以獨也，然則彊固榮辱在於取相矣。身能相能，如是者王，身不能，知恐懼而求能者，如是者彊；身不能，不知恐懼而求能者，安唯便僻左右親比己者之用，如是者危削；綦之而亡。國者，巨用之則大，小用之則小；綦大而王，綦小而亡，小巨分流者存。巨用之者，先義而後利，安不卹親疏，不卹貴賤，唯誠能之求，夫是之謂巨用之。小用之者，先利而後義，安不卹是非，不治曲直，唯便僻親比己者之用，夫是之謂小用之。巨用之者若彼，小用之者若此，小巨分流者，亦一若彼，一若此也。故曰：「粹而王，駁而霸，無一焉而亡。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-8_s-1\",\n        \"xunzi_ch-11_p-8_s-2\",\n        \"xunzi_ch-11_p-8_s-3\",\n        \"xunzi_ch-11_p-8_s-4\",\n        \"xunzi_ch-11_p-8_s-5\",\n        \"xunzi_ch-11_p-8_s-6\",\n        \"xunzi_ch-11_p-8_s-7\",\n        \"xunzi_ch-11_p-8_s-8\",\n        \"xunzi_ch-11_p-8_s-9\",\n        \"xunzi_ch-11_p-8_s-10\",\n        \"xunzi_ch-11_p-8_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"彼持國的人或事，必不可以獨啊，然則彊固榮辱在於取相矣。身能相能，如是的人或事王，身不能，知恐懼而且求能的人或事，如是的人或事彊；身不能，不知恐懼而且求能的人或事，安唯便僻左右親比己的人或事的用，如是的人或事危削；綦的而且亡。國的人或事，巨用的則大，小用的則小；綦大而且王，綦小而且亡，小巨分流的人或事存。巨用的的人或事，先道義正道而且後利，安不卹親疏，不卹貴賤，唯誠能的求，這就是儒家所說的巨用的。小用的的人或事，先利而且後道義正道，安不卹是絕不是，不治曲直，唯便僻親比己的人或事的用，這就是儒家所說的小用的。巨用的的人或事若彼，小用的的人或事若此，小巨分流的人或事，亦一若彼，一若此啊。所以說：粹而且王，駁而且霸，無一焉而且亡。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「彼持國者，必不可以獨也，然則彊固榮辱在於取相矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「持」、「國」、「必」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「彼持國者必不可以獨也然則彊固榮辱在於取相矣身能相」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「身能相能，如是者王，身不能，知恐懼而求能者，如是者彊」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-9\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 9,\n      \"canonicalText\": \"國無禮則不正。禮之所以正國也，譬之：猶衡之於輕重也，猶繩墨之於曲直也，猶規矩之於方圓也，既錯之而人莫之能誣也。《詩》雲：「如霜雪之將將，如日月之光明，為之則存，不為則亡。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-9_s-1\",\n        \"xunzi_ch-11_p-9_s-2\",\n        \"xunzi_ch-11_p-9_s-3\",\n        \"xunzi_ch-11_p-9_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"國無禮正義道義道品德修養規程則不正。禮正義道義道品德修養規程的所以正國啊，譬的：猶衡的於輕重啊，猶繩墨的於曲直啊，猶規矩的於方圓啊，既錯的而且人莫的能誣啊。《詩》雲：如霜雪的將將，如日月的光明，為的則存，不為則亡。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「國無禮則不正」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「國」、「無」、「禮」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「國無禮則不正禮之所以正國也譬之猶衡之於輕重也猶繩」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「禮之所以正國也，譬之：猶衡之於輕重也，猶繩墨之於曲直也，猶規矩之於方圓也，既錯之而人莫之能誣也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 10,\n      \"canonicalText\": \"國危則無樂君，國安則無憂民。亂則國危，治則國安。今君人者，急逐樂而緩治國，豈不過甚矣哉！譬之是由好聲色，而恬無耳目也，豈不哀哉！夫人之情，目欲綦色，耳欲綦聲，口欲綦味，鼻欲綦臭，心欲綦佚。此五綦者，人情之所必不免也。養五綦者有具。無其具，則五綦者不可得而致也。萬乘之國，可謂廣大富厚矣，加有治辨彊固之道焉，若是則恬愉無患難矣，然後養五綦之具具也。故百樂者，生於治國者也；憂患者，生於亂國者也。急逐樂而緩治國者，非知樂者也。故明君者，必將先治其國，然後百樂得其中。闇君者，必將急逐樂而緩治國，故憂患不可勝校也，必至於身死國亡然後止也，豈不哀哉！將以為樂，乃得憂焉；將以為安，乃得危焉；將以為福，乃得死亡焉，豈不哀哉！於乎！君人者，亦可以察若言矣。故治國有道，人主有職。若夫貫日而治詳，一日而曲列之，是所使夫百吏官人為也，不足以是傷遊玩安燕之樂。若夫論一相以兼率之，使臣下百吏莫不宿道鄉方而務，是夫人主之職也。若是則一天下，名配堯禹。之主者，守至約而詳，事至佚而功，垂衣裳，不下簟席之上，而海內之人莫不願得以為帝王。夫是之謂至約，樂莫大焉。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-10_s-1\",\n        \"xunzi_ch-11_p-10_s-2\",\n        \"xunzi_ch-11_p-10_s-3\",\n        \"xunzi_ch-11_p-10_s-4\",\n        \"xunzi_ch-11_p-10_s-5\",\n        \"xunzi_ch-11_p-10_s-6\",\n        \"xunzi_ch-11_p-10_s-7\",\n        \"xunzi_ch-11_p-10_s-8\",\n        \"xunzi_ch-11_p-10_s-9\",\n        \"xunzi_ch-11_p-10_s-10\",\n        \"xunzi_ch-11_p-10_s-11\",\n        \"xunzi_ch-11_p-10_s-12\",\n        \"xunzi_ch-11_p-10_s-13\",\n        \"xunzi_ch-11_p-10_s-14\",\n        \"xunzi_ch-11_p-10_s-15\",\n        \"xunzi_ch-11_p-10_s-16\",\n        \"xunzi_ch-11_p-10_s-17\",\n        \"xunzi_ch-11_p-10_s-18\",\n        \"xunzi_ch-11_p-10_s-19\",\n        \"xunzi_ch-11_p-10_s-20\",\n        \"xunzi_ch-11_p-10_s-21\",\n        \"xunzi_ch-11_p-10_s-22\",\n        \"xunzi_ch-11_p-10_s-23\",\n        \"xunzi_ch-11_p-10_s-24\",\n        \"xunzi_ch-11_p-10_s-25\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"國危則無樂君，國安則無憂民。亂則國危，治則國安。今君人的人或事，急逐樂而且緩治國，豈不過甚矣哉！譬的是由好聲色，而且恬無耳目啊，豈不哀哉！夫人的情，目欲綦色，耳欲綦聲，口欲綦味，鼻欲綦臭，心欲綦佚。此五綦的人或事，人情的所必不免啊。養五綦的人或事有具。無他的具，則五綦的人或事不可得而且致啊。萬乘的國，可謂廣大富厚矣，加有治辨彊固的道焉，若是則恬愉無患難矣，然後養五綦的具具啊。所以百樂的人或事，生於治國的人或事啊；憂患的人或事，生於亂國的人或事啊。急逐樂而且緩治國的人或事，絕不是知樂的人或事啊。所以明君的人或事，必將先治他的國，然後百樂得他的中。闇君的人或事，必將急逐樂而且緩治國，所以憂患不可勝校啊，必至於身死國亡然後止啊，豈不哀哉！將以為樂，乃得憂焉；將以為安，乃得危焉；將以為福，乃得死亡焉，豈不哀哉！於乎！君人的人或事，亦可以察若言矣。所以治國有道，人主有職。至於談到那貫日而且治詳，一日而且曲列的，是所使夫百吏官人為啊，不足以是傷遊玩安燕的樂。至於談到那論一相以兼率的，使臣下百吏莫不宿道鄉方而且務，是夫人主的職啊。若是則一天下，名配堯禹。的主的人或事，守至約而且詳，事至佚而且功，垂衣裳，不下簟席的上，而且海內的人莫不願得以為帝王。這就是儒家所說的至約，樂莫大焉。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「國危則無樂君，國安則無憂民」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「國」、「危」、「無」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「國危則無樂君國安則無憂民亂則國危治則國安今君人者」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「亂則國危，治則國安」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 11,\n      \"canonicalText\": \"人主者，以官人為能者也；匹夫者，以自能為能者也。人主得使人為之，匹夫則無所移之。百畝一守，事業窮，無所移之也。今以一人兼聽天下，日有餘而治不足者，使人為之也。大有天下，小有一國，必自為之然後可，則勞苦秏顇莫甚焉。如是，則雖臧獲不肯與天子易埶業。以是縣天下，一四海，何故必自為之？為之者，役夫之道也，墨子之說也。論德使能而官施之者，聖王之道也，儒之所謹守也。傳曰：農分田而耕，賈分貨而販，百工分事而勸，士大夫分職而聽，建國諸侯之君分土而守，三公摠方而議，則天子共己而已矣。出若入若，天下莫不平均，莫不治辨，是百王之所同也，而禮法之大分也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-11_s-1\",\n        \"xunzi_ch-11_p-11_s-2\",\n        \"xunzi_ch-11_p-11_s-3\",\n        \"xunzi_ch-11_p-11_s-4\",\n        \"xunzi_ch-11_p-11_s-5\",\n        \"xunzi_ch-11_p-11_s-6\",\n        \"xunzi_ch-11_p-11_s-7\",\n        \"xunzi_ch-11_p-11_s-8\",\n        \"xunzi_ch-11_p-11_s-9\",\n        \"xunzi_ch-11_p-11_s-10\",\n        \"xunzi_ch-11_p-11_s-11\",\n        \"xunzi_ch-11_p-11_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"人主的人或事，以官人為能的人或事啊；匹夫的人或事，以自能為能的人或事啊。人主得使人為的，匹夫則無所移的。百畝一守，事業窮，無所移的啊。今以一人兼聽天下，日有餘而且治不足的人或事，使人為的啊。大有天下，小有一國，必自為的然後可，則勞苦秏顇莫甚焉。如是，則雖臧獲不肯與天子易埶業。以是縣天下，一四海，何所以必自為的？為的的人或事，役夫的道啊，墨子的說啊。論德行修養使能而且官施的的人或事，聖王的道啊，儒的所謹守啊。傳說道：農分田而且耕，賈分貨而且販，百工分事而且勸，士大夫分職而且聽，建國諸侯的君分土而且守，三公摠方而且議，則天子共己而且已矣。出若入若，天下莫不平均，莫不治辨，是百王的所同啊，而且禮道義正道道德行修養規程典章法度的大分啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「人主者，以官人為能者也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「人」、「主」、「官」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「人主者以官人為能者也匹夫者以自能為能者也人主得使」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「匹夫者，以自能為能者也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 12,\n      \"canonicalText\": \"百里之地，可以取天下。是不虛；其難者在於人主之知之也。取天下者，非負其土地而從之之謂也，道足以壹人而已矣。彼其人苟壹，則其土地奚去我而適它？故百里之地，其等位爵服，足以容天下之賢士矣；其官職事業，足以容天下之能士矣；循其舊法，擇其善者而明用之，足以順服好利之人矣。賢士一焉，能士官焉，好利之人服焉，三者具而天下盡，無有是其外矣。故百里之地，足以竭埶矣。致忠信，箸仁義，足以竭人矣。兩者合而天下取，諸侯後同者先危。《詩》曰：「自西自東，自南自北，無思不服。」一人之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-12_s-1\",\n        \"xunzi_ch-11_p-12_s-2\",\n        \"xunzi_ch-11_p-12_s-3\",\n        \"xunzi_ch-11_p-12_s-4\",\n        \"xunzi_ch-11_p-12_s-5\",\n        \"xunzi_ch-11_p-12_s-6\",\n        \"xunzi_ch-11_p-12_s-7\",\n        \"xunzi_ch-11_p-12_s-8\",\n        \"xunzi_ch-11_p-12_s-9\",\n        \"xunzi_ch-11_p-12_s-10\",\n        \"xunzi_ch-11_p-12_s-11\",\n        \"xunzi_ch-11_p-12_s-12\",\n        \"xunzi_ch-11_p-12_s-13\",\n        \"xunzi_ch-11_p-12_s-14\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"百里的地，可以取天下。是不虛；他的難的人或事在於人主的知的啊。取天下的人或事，絕不是負他的土地而且從的的謂啊，道足以壹人而且已矣。彼他的人苟壹，則他的土地奚去我而且適它？所以百里的地，他的等位爵服，足以容天下的賢士矣；他的官職事業，足以容天下的能士矣；循他的舊典章法度，擇他的善的人或事而且明用的，足以順服好利的人矣。賢士一焉，能士官焉，好利的人服焉，三的人或事具而且天下盡，無有是他的外矣。所以百里的地，足以竭埶矣。致忠信，箸仁愛之德道義正道，足以竭人矣。兩的人或事合而且天下取，諸侯後同的人或事先危。《詩》說道：自西自東，自南自北，無思不服。一人的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「百里之地，可以取天下」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「百」、「里」、「地」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「百里之地可以取天下是不虛其難者在於人主之知之也取」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「是不虛」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 13,\n      \"canonicalText\": \"羿、蜂門者，善服射者也；王良、造父者，善服馭者也。聰明君子者，善服人者也。人服而埶從之，人不服而埶去之，故王者已於服人矣。故人主欲得善射，射遠中微，則莫若羿、蜂門矣；欲得善馭，及速致遠，則莫若王良、造父矣。欲得調壹天下，制秦楚，則莫若聰明君子矣。其用知甚簡，其為事不勞，而功名致大，甚易處而極可樂也。故明君以為寶，而愚者以為難。夫貴為天子，富有天下，名為聖王，兼制人，人莫得而制也，是人情之所同欲也，而王者兼而有是者也。重色而衣之，重味而食之，重財物而制之，合天下而君之，飲食甚厚，聲樂甚大，臺謝甚高，園囿甚廣，臣使諸侯，一天下，是又人情之所同欲也，而天子之禮制如是者也。制度以陳，政令以挾，官人失要則死，公侯失禮則幽，四方之國，有侈離之德則必滅，名聲若日月，功績如天地，天下之人應之如景嚮，是又人情之所同欲也，而王者兼而有是者也。故人之情，口好味，而臭味莫美焉；耳好聲，而聲樂莫大焉；目好色，而文章致繁，婦女莫眾焉；形體好佚，而安重閒靜莫愉焉；心好利，而穀祿莫厚焉。合天下之所同願兼而有之，睪牢天下而制之若制子孫，人苟不狂惑戇陋者，其誰能睹是而不樂也哉！欲是之主，並肩而存；能建是之士，不世絕；千歲而不合，何也？曰：人主不公，人臣不忠也。人主則外賢而偏舉，人臣則爭職而妒賢，是其所以不合之故也。人主胡不廣焉，無卹親疏，無偏貴賤，惟誠能之求？若是，則人臣輕職業讓賢，而安隨其後。如是，則舜禹還至，王業還起；功壹天下，名配舜禹，物由有可樂，如是其美焉者乎！嗚呼！君人者，亦可以察若言矣。楊朱哭衢塗，曰：「此夫過舉蹞步，而覺跌千里者夫！」哀哭之。此亦榮辱、安危、存亡之衢已，此其為可哀，甚於衢塗。嗚呼！哀哉！君人者，千歲而不覺也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-13_s-1\",\n        \"xunzi_ch-11_p-13_s-2\",\n        \"xunzi_ch-11_p-13_s-3\",\n        \"xunzi_ch-11_p-13_s-4\",\n        \"xunzi_ch-11_p-13_s-5\",\n        \"xunzi_ch-11_p-13_s-6\",\n        \"xunzi_ch-11_p-13_s-7\",\n        \"xunzi_ch-11_p-13_s-8\",\n        \"xunzi_ch-11_p-13_s-9\",\n        \"xunzi_ch-11_p-13_s-10\",\n        \"xunzi_ch-11_p-13_s-11\",\n        \"xunzi_ch-11_p-13_s-12\",\n        \"xunzi_ch-11_p-13_s-13\",\n        \"xunzi_ch-11_p-13_s-14\",\n        \"xunzi_ch-11_p-13_s-15\",\n        \"xunzi_ch-11_p-13_s-16\",\n        \"xunzi_ch-11_p-13_s-17\",\n        \"xunzi_ch-11_p-13_s-18\",\n        \"xunzi_ch-11_p-13_s-19\",\n        \"xunzi_ch-11_p-13_s-20\",\n        \"xunzi_ch-11_p-13_s-21\",\n        \"xunzi_ch-11_p-13_s-22\",\n        \"xunzi_ch-11_p-13_s-23\",\n        \"xunzi_ch-11_p-13_s-24\",\n        \"xunzi_ch-11_p-13_s-25\",\n        \"xunzi_ch-11_p-13_s-26\",\n        \"xunzi_ch-11_p-13_s-27\",\n        \"xunzi_ch-11_p-13_s-28\",\n        \"xunzi_ch-11_p-13_s-29\",\n        \"xunzi_ch-11_p-13_s-30\",\n        \"xunzi_ch-11_p-13_s-31\",\n        \"xunzi_ch-11_p-13_s-32\",\n        \"xunzi_ch-11_p-13_s-33\",\n        \"xunzi_ch-11_p-13_s-34\",\n        \"xunzi_ch-11_p-13_s-35\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"羿、蜂門的人或事，善服射的人或事啊；王良、造父的人或事，善服馭的人或事啊。聰明君子的人或事，善服人的人或事啊。人服而且埶從的，人不服而且埶去的，所以王的人或事已於服人矣。所以人主欲得善射，射遠中微，則莫若羿、蜂門矣；欲得善馭，及速致遠，則莫若王良、造父矣。欲得調壹天下，制秦楚，則莫若聰明君子矣。他的用知甚簡，他的為事不勞，而且功名致大，甚易處而且極可樂啊。所以明君以為寶，而且愚的人或事以為難。夫貴為天子，富有天下，名為聖王，兼制人，人莫得而且制啊，是人情的所同欲啊，而且王的人或事兼而且有是的人或事啊。重色而且衣的，重味而且食的，重財物而且制的，合天下而且君的，飲食甚厚，聲樂甚大，臺謝甚高，園囿甚廣，臣使諸侯，一天下，是又人情的所同欲啊，而且天子的禮道義正道道德行修養規程制如是的人或事啊。制度以陳，政令以挾，官人失要則死，公侯失禮道義正道道德行修養規程則幽，四方的國，有侈離的德行修養則必滅，名聲若日月，功績如天地，天下的人應的如景嚮，是又人情的所同欲啊，而且王的人或事兼而且有是的人或事啊。所以人的情，口好味，而且臭味莫美焉；耳好聲，而且聲樂莫大焉；目好色，而且文章致繁，婦女莫眾焉；形體好佚，而且安重閒靜莫愉焉；心好利，而且穀祿莫厚焉。合天下的所同願兼而且有的，睪牢天下而且制的若制子孫，人苟不狂惑戇陋的人或事，他的誰能睹是而且不樂啊哉！欲是的主，並肩而且存；能建是的士，不世絕；千歲而且不合，何啊？說道：人主不公，人臣不忠啊。人主則外賢而且偏舉，人臣則爭職而且妒賢，是他的所以不合的所以啊。人主胡不廣焉，無卹親疏，無偏貴賤，惟誠能的求？若是，則人臣輕職業讓賢，而且安隨他的後。如是，則舜禹還至，王業還起；功壹天下，名配舜禹，物由有可樂，如是他的美焉的人或事乎！嗚呼！君人的人或事，亦可以察若言矣。楊朱哭衢塗，說道：此夫過舉蹞步，而且覺跌千里的人或事夫！哀哭的。此亦榮辱、安危、存亡的衢已，此他的為可哀，甚於衢塗。哀哉！君人的人或事，千歲而且不覺啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「羿、蜂門者，善服射者也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「羿」、「蜂」、「門」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「羿蜂門者善服射者也王良造父者善服馭者也聰明君子者」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「王良、造父者，善服馭者也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 14,\n      \"canonicalText\": \"無國而不有治法，無國而不有亂法；無國而不有賢士，無國而不有罷士；無國而不有願民，無國而不有悍民；無國而不有美俗，無國而不有惡俗。兩者並行而國在，上偏而國安，在下偏而國危；上一而王，下一而亡。故其法治，其佐賢，其民願，其俗美，而四者齊，夫是之謂上一。如是則不戰而勝，不攻而得，甲兵不勞而天下服。故湯以亳，文王以鄗，皆百里之地也，天下為一，諸侯為臣，通達之屬，莫不從服，無它故焉，四者齊也。桀紂即厚於有天下之埶，索為匹夫而不可得也，是無它故焉，四者並亡也。故百王之法不同，若是所歸者一也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-14_s-1\",\n        \"xunzi_ch-11_p-14_s-2\",\n        \"xunzi_ch-11_p-14_s-3\",\n        \"xunzi_ch-11_p-14_s-4\",\n        \"xunzi_ch-11_p-14_s-5\",\n        \"xunzi_ch-11_p-14_s-6\",\n        \"xunzi_ch-11_p-14_s-7\",\n        \"xunzi_ch-11_p-14_s-8\",\n        \"xunzi_ch-11_p-14_s-9\",\n        \"xunzi_ch-11_p-14_s-10\",\n        \"xunzi_ch-11_p-14_s-11\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"無國而且不有治典章法度，無國而且不有亂典章法度；無國而且不有賢士，無國而且不有罷士；無國而且不有願民，無國而且不有悍民；無國而且不有美俗，無國而且不有惡俗。兩的人或事並行而且國在，上偏而且國安，在下偏而且國危；上一而且王，下一而且亡。所以他的典章法度治，他的佐賢，他的民願，他的俗美，而且四的人或事齊，這就是儒家所說的上一。如是則不戰而且勝，不攻而且得，甲兵不勞而且天下服。所以湯以亳，文王以鄗，皆百里的地啊，天下為一，諸侯為臣，通達的屬，莫不從服，無它所以焉，四的人或事齊啊。桀紂即厚1於有天下的埶，索為匹夫而且不可得啊，是無它所以焉，四的人或事並亡啊。所以百王的典章法度不同，若是所歸的人或事一啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「無國而不有治法，無國而不有亂法」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「無」、「國」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「無國而不有治法無國而不有亂法無國而不有賢士無國而」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「無國而不有賢士，無國而不有罷士」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 15,\n      \"canonicalText\": \"上莫不致愛其下，而制之以禮。上之於下，如保赤子，政令制度，所以接下之人百姓，有不理者如豪末，則雖孤獨鰥寡必不加焉。故下之親上，歡如父母，可殺而不可使不順。君臣上下，貴賤長幼，至於庶人，莫不以是為隆正；然後皆內自省，以謹於分。是百王之所以同也，而禮法之樞要也。然後農分田而耕，賈分貨而販，百工分事而勸，士大夫分職而聽，建國諸侯之君分土而守，三公總方而議，則天子共己而止矣。出若入若，天下莫不均平，莫不治辨。是百王之所同，而禮法之大分也。若夫貫日而治平，權物而稱用，使衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜，以是用挾於萬物，尺寸尋丈，莫得不循乎制度數量然後行，則是官人使吏之事也，不足數於大君子之前。故君人者，立隆政本朝而當，所使要百事者誠仁人也，則身佚而國治，功大而名美，上可以王，下可以霸。立隆正本朝而不當，所使要百事者非仁人也，則身勞而國亂，功廢而名辱，社稷必危，是人君者之樞機也。故能當一人而天下取，失當一人而社稷危。不能當一人，而能當千百人者，說無之有也。既能當一人，則身有何勞而為？垂衣裳而天下定。故湯用伊尹，文王用呂尚，武王用召公，成王用周公旦。卑者五伯，齊桓公閨門之內，縣樂、奢泰、遊抏之脩，於天下不見謂脩，然九合諸侯，一匡天下，為五伯長，是亦無他故焉，知一政於管仲也，是君人者之要守也。知者易為之興力，而功名綦大。舍是而孰足為也？故古之人，有大功名者，必道是者也。喪其國危其身者，必反是者也。故孔子曰：「知者之知，固以多矣，有以守少，能無察乎？愚者之知，固以少矣，有以守多，能無狂乎？」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-15_s-1\",\n        \"xunzi_ch-11_p-15_s-2\",\n        \"xunzi_ch-11_p-15_s-3\",\n        \"xunzi_ch-11_p-15_s-4\",\n        \"xunzi_ch-11_p-15_s-5\",\n        \"xunzi_ch-11_p-15_s-6\",\n        \"xunzi_ch-11_p-15_s-7\",\n        \"xunzi_ch-11_p-15_s-8\",\n        \"xunzi_ch-11_p-15_s-9\",\n        \"xunzi_ch-11_p-15_s-10\",\n        \"xunzi_ch-11_p-15_s-11\",\n        \"xunzi_ch-11_p-15_s-12\",\n        \"xunzi_ch-11_p-15_s-13\",\n        \"xunzi_ch-11_p-15_s-14\",\n        \"xunzi_ch-11_p-15_s-15\",\n        \"xunzi_ch-11_p-15_s-16\",\n        \"xunzi_ch-11_p-15_s-17\",\n        \"xunzi_ch-11_p-15_s-18\",\n        \"xunzi_ch-11_p-15_s-19\",\n        \"xunzi_ch-11_p-15_s-20\",\n        \"xunzi_ch-11_p-15_s-21\",\n        \"xunzi_ch-11_p-15_s-22\",\n        \"xunzi_ch-11_p-15_s-23\",\n        \"xunzi_ch-11_p-15_s-24\",\n        \"xunzi_ch-11_p-15_s-25\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"上莫不致愛他的下，而且制的以禮道義正道道德行修養規程。上的於下，如保赤子，政令制度，所以接下的人百姓，有不理的人或事如豪末，則雖孤獨鰥寡必不加焉。所以下的親上，歡如父母，可殺而且不可使不順。君臣上下，貴賤長幼，至於庶人，莫不以是為隆正；然後皆內自省，以謹於分。是百王的所以同啊，而且禮道義正道道德行修養規程典章法度的樞要啊。然後農分田而且耕，賈分貨而且販，百工分事而且勸，士大夫分職而且聽，建國諸侯的君分土而且守，三公總方而且議，則天子共己而且止矣。出若入若，天下莫不均平，莫不治辨。是百王的所同，而且禮道義正道道德行修養規程典章法度的大分啊。至於談到那貫日而且治平，權物而且稱用，使衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜，以是用挾於萬物，尺寸尋丈，莫得不循乎制度數量然後行，則是官人使吏的事啊，不足數於大君子的前。所以君人的人或事，立隆政本朝而且當，所使要百事的人或事誠仁愛之德人啊，則身佚而且國治，功大而且名美，上可以王，下可以霸。立隆正本朝而且不當，所使要百事的人或事絕不是仁愛之德人啊，則身勞而且國亂，功廢而且名辱，社稷必危，是人君的人或事的樞機啊。所以能當一人而且天下取，失當一人而且社稷危。不能當一人，而且能當千百人的人或事，說無的有啊。既能當一人，則身有何勞而且為？垂衣裳而且天下定。所以湯用伊尹，文王用呂尚，武王用召公，成王用周公旦。卑的人或事五伯，齊桓公閨門的內，縣樂、奢泰、遊抏的脩，於天下不見謂脩，然九合諸侯，一匡天下，為五伯長，是亦無他所以焉，知一政於管仲啊，是君人的人或事的要守啊。知的人或事易為的興力，而且功名綦大。舍是而且孰足為啊？所以古的人，有大功名的人或事，必道是的人或事啊。喪他的國危他的身的人或事，必反是的人或事啊。所以孔子說道：知的人或事的知，固以多矣，有以守少，能無察乎？愚的人或事的知，固以少矣，有以守多，能無狂乎？此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「上莫不致愛其下，而制之以禮」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「上」、「莫」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「上莫不致愛其下而制之以禮上之於下如保赤子政令制度」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「上之於下，如保赤子，政令制度，所以接下之人百姓，有不理者如豪末，則雖孤獨鰥寡必不加焉」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-16\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 16,\n      \"canonicalText\": \"治國者分已定，則主相臣下百吏，各謹其所聞，不務聽其所不聞；各謹其所見，不務視其所不見。所聞所見誠以齊矣。則雖幽閒隱闢，百姓莫敢不敬分安制，以化其上，是治國之徵也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-16_s-1\",\n        \"xunzi_ch-11_p-16_s-2\",\n        \"xunzi_ch-11_p-16_s-3\",\n        \"xunzi_ch-11_p-16_s-4\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"治國的人或事分已定，則主相臣下百吏，各謹他的所聞，不務聽他的所不聞；各謹他的所見，不務視他的所不見。所聞所見誠以齊矣。則雖幽閒隱闢，百姓莫敢不敬分安制，以化他的上，是治國的徵啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「治國者分已定，則主相臣下百吏，各謹其所聞，不務聽其所不聞」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「治」、「國」、「分」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「治國者分已定則主相臣下百吏各謹其所聞不務聽其所不」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「各謹其所見，不務視其所不見」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 17,\n      \"canonicalText\": \"主道治近不治遠，治明不治幽，治一不治二。主能治近則遠者理，主能治明則幽者化，主能當一則百事正。夫兼聽天下，日有餘而治不足者，如此也，是治之極也。既能治近，又務治遠；既能治明，又務見幽；既能當一，又務正百，是過者也，過猶不及也。闢之是猶立直木而求其影之枉也。不能治近，又務治遠；不能察明，又務見幽；不能當一，又務正百，是悖者也。闢之是猶立枉木而求其影之直也。故明主好要，而闇主好詳；主好要則百事詳，主好詳則百事荒。君者、論一相，陳一法，明一指，以兼覆之，兼炤之，以觀其盛者也。相者，論列百官之長，要百事之聽，以飾朝廷臣下百吏之分，度其功勞，論其慶賞，歲終奉其成功以效於君。當則可，不當則廢。故君人勞於索之，而休於使之。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-17_s-1\",\n        \"xunzi_ch-11_p-17_s-2\",\n        \"xunzi_ch-11_p-17_s-3\",\n        \"xunzi_ch-11_p-17_s-4\",\n        \"xunzi_ch-11_p-17_s-5\",\n        \"xunzi_ch-11_p-17_s-6\",\n        \"xunzi_ch-11_p-17_s-7\",\n        \"xunzi_ch-11_p-17_s-8\",\n        \"xunzi_ch-11_p-17_s-9\",\n        \"xunzi_ch-11_p-17_s-10\",\n        \"xunzi_ch-11_p-17_s-11\",\n        \"xunzi_ch-11_p-17_s-12\",\n        \"xunzi_ch-11_p-17_s-13\",\n        \"xunzi_ch-11_p-17_s-14\",\n        \"xunzi_ch-11_p-17_s-15\",\n        \"xunzi_ch-11_p-17_s-16\",\n        \"xunzi_ch-11_p-17_s-17\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"主道治近不治遠，治明不治幽，治一不治二。主能治近則遠的人或事理，主能治明則幽的人或事化，主能當一則百事正。夫兼聽天下，日有餘而且治不足的人或事，如此啊，是治的極啊。既能治近，又務治遠；既能治明，又務見幽；既能當一，又務正百，是過的人或事啊，過猶不及啊。闢的是猶立直木而且求他的影的枉啊。不能治近，又務治遠；不能察明，又務見幽；不能當一，又務正百，是悖的人或事啊。闢的是猶立枉木而且求他的影的直啊。所以明主好要，而且闇主好詳；主好要則百事詳，主好詳則百事荒。君的人或事、論一相，陳一典章法度，明一指，以兼覆的，兼炤的，以觀他的盛的人或事啊。相的人或事，論列百官的長，要百事的聽，以飾朝廷臣下百吏的分，度他的功勞，論他的慶賞，歲終奉他的成功以效於君。當則可，不當則廢。所以君人勞於索的，而且休於使的。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「主道治近不治遠，治明不治幽，治一不治二」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「主」、「道」、「治」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「主道治近不治遠治明不治幽治一不治二主能治近則遠者」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「主能治近則遠者理，主能治明則幽者化，主能當一則百事正」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 18,\n      \"canonicalText\": \"用國者，得百姓之力者富，得百姓之死者彊，得百姓之譽者榮。三得者具而天下歸之，三得者亡而天下去之；天下歸之之謂王，天下去之之謂亡。湯武者，脩其道，行其義，興天下同利，除天下同害，天下歸之。故厚德音以先之，明禮義以道之，致忠信以愛之，賞賢使能以次之，爵服賞慶以申重之，時其事，輕其任，以調齊之，潢然兼覆之，養長之，如保赤子。生民則致寬，使民則綦理，辯政令制度，所以接天下之人百姓，有非理者如豪末，則雖孤獨鰥寡，必不加焉。是故百姓貴之如帝，親之如父母，為之出死斷亡而不愉者，無它故焉，道德誠明，利澤誠厚也。亂世不然，汙漫突盜以先之，權謀傾覆以示之，俳優、侏儒、婦女之請謁以悖之，使愚詔知，使不肖臨賢，生民則致貧隘，使民則極勞苦。是故，百姓賤之如尪，惡之如鬼，日欲司閒而相與投藉之，去逐之。卒有寇難之事，又望百姓之為己死，不可得也，說無以取之焉。孔子曰：「審吾所以適人，適人之所以來我也。」此之謂也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-18_s-1\",\n        \"xunzi_ch-11_p-18_s-2\",\n        \"xunzi_ch-11_p-18_s-3\",\n        \"xunzi_ch-11_p-18_s-4\",\n        \"xunzi_ch-11_p-18_s-5\",\n        \"xunzi_ch-11_p-18_s-6\",\n        \"xunzi_ch-11_p-18_s-7\",\n        \"xunzi_ch-11_p-18_s-8\",\n        \"xunzi_ch-11_p-18_s-9\",\n        \"xunzi_ch-11_p-18_s-10\",\n        \"xunzi_ch-11_p-18_s-11\",\n        \"xunzi_ch-11_p-18_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"用國的人或事，得百姓的力的人或事富，得百姓的死的人或事彊，得百姓的譽的人或事榮。三得的人或事具而且天下歸的，三得的人或事亡而且天下去的；天下歸的的謂王，天下去的的謂亡。湯武的人或事，脩他的道，行他的道義正道，興天下同利，除天下同害，天下歸的。所以厚德行修養音以先的，明禮道義正道道德行修養規程道義正道以道的，致忠信以愛的，賞賢使能以次的，爵服賞慶以申重的，時他的事，輕他的任，以調齊的，潢然兼覆的，養長的，如保赤子。生民則致寬，使民則綦理，辯政令制度，所以接天下的人百姓，有絕不是理的人或事如豪末，則雖孤獨鰥寡，必不加焉。正因為如此百姓貴的如帝，親的如父母，為的出死斷亡而且不愉的人或事，無它所以焉，道德行修養誠明，利澤誠厚啊。亂世不然，汙漫突盜以先的，權謀傾覆以示的，俳優、侏儒、婦女的請謁以悖的，使愚詔知，使不肖臨賢，生民則致貧隘，使民則極勞苦。正因為如此，百姓賤的如尪，惡的如鬼，日欲司閒而且相與投藉的，去逐的。卒有寇難的事，又望百姓的為己死，不可得啊，說無以取的焉。孔子說道：審吾所以適人，適人的所以來我啊。此的謂啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「用國者，得百姓之力者富，得百姓之死者彊，得百姓之譽者榮」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「用」、「國」、「得」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「用國者得百姓之力者富得百姓之死者彊得百姓之譽者榮」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「三得者具而天下歸之，三得者亡而天下去之」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 19,\n      \"canonicalText\": \"傷國者，何也？曰：以小人尚民而威，以非所取於民而巧，是傷國之大災也。大國之主也，而好見小利，是傷國。其於聲色、臺榭、園囿也，愈厭而好新，是傷國。不好脩正其所以有，啖啖常欲人之有，是傷國。三邪者在匈中，而又好以權謀傾覆之人，斷事其外，若是，則權輕名辱，社稷必危，是傷國者也。大國之主也，不隆本行，不敬舊法，而好詐故，若是，則夫朝廷群臣，亦從而成俗於不隆禮義而好傾覆也。朝廷群臣之俗若是，則夫眾庶百姓亦從而成俗於不隆禮義而好貪利矣。君臣上下之俗，莫不若是，則地雖廣，權必輕；人雖眾，兵必弱；刑罰雖繁，令不下通。夫是之謂危國，是傷國者也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-19_s-1\",\n        \"xunzi_ch-11_p-19_s-2\",\n        \"xunzi_ch-11_p-19_s-3\",\n        \"xunzi_ch-11_p-19_s-4\",\n        \"xunzi_ch-11_p-19_s-5\",\n        \"xunzi_ch-11_p-19_s-6\",\n        \"xunzi_ch-11_p-19_s-7\",\n        \"xunzi_ch-11_p-19_s-8\",\n        \"xunzi_ch-11_p-19_s-9\",\n        \"xunzi_ch-11_p-19_s-10\",\n        \"xunzi_ch-11_p-19_s-11\",\n        \"xunzi_ch-11_p-19_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"傷國的人或事，何啊？說道：以小人尚民而且威，以絕不是所取於民而且巧，是傷國的大災啊。大國的主啊，而且好見小利，是傷國。他的於聲色、臺榭、園囿啊，愈厭而且好新，是傷國。不好脩正他的所以有，啖啖常欲人的有，是傷國。三邪的人或事在匈中，而且又好以權謀傾覆的人，斷事他的外，若是，則權輕名辱，社稷必危，是傷國的人或事啊。大國的主啊，不隆本行，不敬舊典章法度，而且好詐所以，若是，則夫朝廷群臣，亦從而且成俗於不隆禮道義正道道德行修養規程道義正道而且好傾覆啊。朝廷群臣的俗若是，則夫眾庶百姓亦從而且成俗於不隆禮道義正道道德行修養規程道義正道而且好貪利矣。君臣上下的俗，莫不若是，則地雖廣，權必輕；人雖眾，兵必弱；刑罰雖繁，令不下通。這就是儒家所說的危國，是傷國的人或事啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「傷國者，何也」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「傷」、「國」、「何」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「傷國者何也曰以小人尚民而威以非所取於民而巧是傷國」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「曰：以小人尚民而威，以非所取於民而巧，是傷國之大災也」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"order\": 20,\n      \"canonicalText\": \"儒者為之不然，必將曲辨：朝廷必將隆禮義而審貴賤，若是、則士大夫莫不敬節死制者矣。百官則將齊其制度，重其官秩，若是、則百吏莫不畏法而遵繩矣。關市幾而不徵，質律禁止而不偏，如是、則商賈莫不敦愨而無詐矣。百工將時斬伐，佻其期日，而利其巧任，如是，則百工莫不忠信而不楛矣。縣鄙則將輕田野之稅，省刀布之歛，罕舉力役，無奪農時，如是、農夫莫不樸力而寡能矣。士大夫務節死制，然而兵勁。百吏畏法循繩，然後國常不亂。商賈敦愨無詐，則商旅安，貨通財，而國求給矣。百工忠信而不楛，則器用巧便而財不匱矣。農夫樸力而寡能，則上不失天時，下不失地利，中得人和，而百事不廢。是之謂政令行，風俗美，以守則固，以徵則彊，居則有名，動則有功。此儒之所謂曲辨也。\",\n      \"sentenceIds\": [\n        \"xunzi_ch-11_p-20_s-1\",\n        \"xunzi_ch-11_p-20_s-2\",\n        \"xunzi_ch-11_p-20_s-3\",\n        \"xunzi_ch-11_p-20_s-4\",\n        \"xunzi_ch-11_p-20_s-5\",\n        \"xunzi_ch-11_p-20_s-6\",\n        \"xunzi_ch-11_p-20_s-7\",\n        \"xunzi_ch-11_p-20_s-8\",\n        \"xunzi_ch-11_p-20_s-9\",\n        \"xunzi_ch-11_p-20_s-10\",\n        \"xunzi_ch-11_p-20_s-11\",\n        \"xunzi_ch-11_p-20_s-12\"\n      ],\n      \"sourceRefs\": [\n        {\n          \"label\": \"《荀子》—中國哲學書電子化計劃\",\n          \"edition\": \"王先謙《荀子集解》本\",\n          \"location\": \"https://ctext.org/xunzi/zh\",\n          \"accessedAt\": \"2026-08-31\"\n        },\n        {\n          \"label\": \"《荀子》—維基文庫\",\n          \"edition\": \"楊倞注《荀子》四部叢刊本\",\n          \"location\": \"https://zh.wikisource.org/zh-hant/荀子\",\n          \"accessedAt\": \"2026-08-31\"\n        }\n      ],\n      \"readingAid\": {\n        \"translation\": \"儒的人或事為的不然，必將曲辨：朝廷必將隆禮道義正道道德行修養規程道義正道而且審貴賤，若是、則士大夫莫不敬節死制的人或事矣。百官則將齊他的制度，重他的官秩，若是、則百吏莫不畏典章法度而且遵繩矣。關市幾而且不徵，質律禁止而且不偏，如是、則商賈莫不敦愨而且無詐矣。百工將時斬伐，佻他的期日，而且利他的巧任，如是，則百工莫不忠信而且不楛矣。縣鄙則將輕田野的稅，省刀布的歛，罕舉力役，無奪農時，如是、農夫莫不樸力而且寡能矣。士大夫務節死制，然而且兵勁。百吏畏典章法度循繩，然後國常不亂。商賈敦愨無詐，則商旅安，貨通財，而且國求給矣。百工忠信而且不楛，則器用巧便而且財不匱矣。農夫樸力而且寡能，則上不失天時，下不失地利，中得人和，而且百事不廢。是的謂政令行，風俗美，以守則固，以徵則彊，居則有名，動則有功。此儒的所謂曲辨啊。\",\n        \"analysis\": \"【荀學篇旨與核心哲思】\\n本節選自先秦儒家集大成名著《荀子》〈王霸〉。荀子立足於戰國後期的政治實踐，開篇「儒者為之不然，必將曲辨：朝廷必將隆禮義而審貴賤，若是、則士大夫莫不敬節死制者矣」立論高遠，展現隆禮重法、化性起偽與富國強兵之博大經學架構。\\n\\n【禮法名物與先秦訓詁】\\n依唐楊倞注與清王先謙《荀子集解》，深入考釋「儒」、「為」、「不」等核心儒學範疇，嚴格辨明人性自私實然與後天人為禮法偽故之本質差別，訓詁精審，名實相副。\\n\\n【明分使群與嚴密論辯】\\n論辯雄渾嚴密、譬喻層出，引述「儒者為之不然必將曲辨朝廷必將隆禮義而審貴賤若是則」層層推進，以整飭駢散結合之句式剖析社會階層分工與名分秩序，強調「明分使群」乃消弭爭奪、凝聚社會之根本法則。\\n\\n【化性起偽與經世大成】\\n「百官則將齊其制度，重其官秩，若是、則百吏莫不畏法而遵繩矣」深刻彰顯後天篤學力行之非凡意義，兼綜儒家仁義禮樂與法家制度實效，將道德修養落實為具體的國家治理體系，奠定後世兩千餘年大一統帝國之制度思想根基。\",\n        \"historicalContext\": \"\",\n        \"keywords\": []\n      }\n    }\n  ],\n  \"sentences\": [\n    {\n      \"id\": \"xunzi_ch-11_p-1_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-1\",\n      \"order\": 1,\n      \"canonicalText\": \"國者，天下之制，利用也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-1_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-1\",\n      \"order\": 2,\n      \"canonicalText\": \"人主者，天下之利埶也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-1_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-1\",\n      \"order\": 3,\n      \"canonicalText\": \"得道以持之，則大安也，大榮也，積美之源也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-1_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-1\",\n      \"order\": 4,\n      \"canonicalText\": \"不得道以持之，則大危也，大累也，有之不如無之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-1_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-1\",\n      \"order\": 5,\n      \"canonicalText\": \"及其綦也，索為匹夫不可得也，齊湣、宋獻是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-1_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-1\",\n      \"order\": 6,\n      \"canonicalText\": \"故人主天下之利埶也，然而不能自安也，安之者必將道也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 1,\n      \"canonicalText\": \"故用國者，義立而王，信立而霸，權謀立而亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 2,\n      \"canonicalText\": \"三者明主之所謹擇也，仁人之所務白也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 3,\n      \"canonicalText\": \"絜國以呼禮義，而無以害之，行一不義，殺一無罪，而得天下，仁者不為也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 4,\n      \"canonicalText\": \"擽然扶持心國，且若是其固也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 5,\n      \"canonicalText\": \"所與為之者，之人則舉義士也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 6,\n      \"canonicalText\": \"所以為布陳於國家刑法者，則舉義法也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 7,\n      \"canonicalText\": \"主之所極然帥群臣而首鄉之者，則舉義志也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 8,\n      \"canonicalText\": \"如是則下仰上以義矣，是綦定也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 9,\n      \"canonicalText\": \"綦定而國定，國定而天下定。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 10,\n      \"canonicalText\": \"仲尼無置錐之地，誠義乎志意，加義乎身行，箸之言語，濟之日，不隱乎天下，名垂乎後世。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 11,\n      \"canonicalText\": \"今亦以天下之顯諸侯，誠義乎志意，加義乎法則度量，箸之以政事，案申重之以貴賤殺生，使襲然終始猶一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 12,\n      \"canonicalText\": \"如是，則夫名聲之部發於天地之間也，豈不如日月雷霆然矣哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 13,\n      \"canonicalText\": \"故曰：以國齊義，一日而白，湯武是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 14,\n      \"canonicalText\": \"湯以亳，武王以鄗，皆百里之地也，天下為一，諸侯為臣，通達之屬，莫不從服，無它故焉，以義濟矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-2_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-2\",\n      \"order\": 15,\n      \"canonicalText\": \"是所謂義立而王也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 1,\n      \"canonicalText\": \"德雖未至也，義雖未濟也，然而天下之理略奏矣，刑賞已諾信乎天下矣，臣下曉然皆知其可要也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 2,\n      \"canonicalText\": \"政令已陳，雖睹利敗，不欺其民；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 3,\n      \"canonicalText\": \"約結已定，雖睹利敗，不欺其與。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 4,\n      \"canonicalText\": \"如是，則兵勁城固，敵國畏之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 5,\n      \"canonicalText\": \"國一綦明，與國信之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 6,\n      \"canonicalText\": \"雖在僻陋之國，威動天下，五伯是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 7,\n      \"canonicalText\": \"非本政教也，非致隆高也，非綦文理也，非服人之心也，鄉方略，審勞佚，謹畜積，脩戰備，齺然上下相信，而天下莫之敢當。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 8,\n      \"canonicalText\": \"故齊桓、晉文、楚莊、吳闔閭、越勾踐，是皆僻陋之國也，威動天下，彊殆中國，無它故焉，略信也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-3_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-3\",\n      \"order\": 9,\n      \"canonicalText\": \"是所謂信立而霸也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 1,\n      \"canonicalText\": \"絜國以呼功利，不務張其義，齊其信，唯利之求，內則不憚詐其民，而求小利焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 2,\n      \"canonicalText\": \"外則不憚詐其與，而求大利焉，內不脩正其所以有，然常欲人之有。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 3,\n      \"canonicalText\": \"如是，則臣下百姓莫不以詐心待其上矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 4,\n      \"canonicalText\": \"上詐其下，下詐其上，則是上下析也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 5,\n      \"canonicalText\": \"如是，則敵國輕之，與國疑之，權謀日行，而國不免危削，綦之而亡，齊閔、薛公是也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 6,\n      \"canonicalText\": \"故用彊齊，非以修禮義也，非以本政教也，非以一天下也，綿綿常以結引馳外為務。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 7,\n      \"canonicalText\": \"故彊、南足以破楚，西足以詘秦，北足以敗燕，中足以舉宋。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 8,\n      \"canonicalText\": \"及以燕趙起而攻之，若振槁然，而身死國亡，為天下大戮，後世言惡，則必稽焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-4_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-4\",\n      \"order\": 9,\n      \"canonicalText\": \"是無它故焉，唯其不由禮義，而由權謀也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-5_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-5\",\n      \"order\": 1,\n      \"canonicalText\": \"三者明主之所以謹擇也，而仁人之所以務白也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-5_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-5\",\n      \"order\": 2,\n      \"canonicalText\": \"善擇者制人，不善擇者人制之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 1,\n      \"canonicalText\": \"國者、天下之大器也，重任也，不可不善為擇所而後錯之，錯險則危；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 2,\n      \"canonicalText\": \"不可不善為擇道然後道之，塗薉則塞；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 3,\n      \"canonicalText\": \"危塞則亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 4,\n      \"canonicalText\": \"彼國錯者，非封焉之謂也，何法之道，誰子之與也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 5,\n      \"canonicalText\": \"故道王者之法，與王者之人為之，則亦王；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 6,\n      \"canonicalText\": \"道霸者之法，與霸者之人為之，則亦霸；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 7,\n      \"canonicalText\": \"道亡國之法，與亡國之人為之，則亦亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-6_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-6\",\n      \"order\": 8,\n      \"canonicalText\": \"三者明主之所以謹擇也，而仁人之所以務白也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 1,\n      \"canonicalText\": \"故國者、重任也，不以積持之則不立。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 2,\n      \"canonicalText\": \"故國者，世所以新者也，是憚，憚、非變也，改王改行也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 3,\n      \"canonicalText\": \"故一朝之日也，一日之人也，然而厭焉有千歲之國，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 4,\n      \"canonicalText\": \"曰：援夫千歲之信法以持之也，安與夫千歲之信士為之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 5,\n      \"canonicalText\": \"人無百歲之壽，而有千歲之信士，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 6,\n      \"canonicalText\": \"曰：以夫千歲之法自持者，是乃千歲之信士矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 7,\n      \"canonicalText\": \"故與積禮義之君子為之則王，與端誠信全之士為之則霸，與權謀傾覆之人為之則亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 8,\n      \"canonicalText\": \"三者明主之所以謹擇也，仁人之所以務白也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-7_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-7\",\n      \"order\": 9,\n      \"canonicalText\": \"善擇之者制人，不善擇之者人制之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 1,\n      \"canonicalText\": \"彼持國者，必不可以獨也，然則彊固榮辱在於取相矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 2,\n      \"canonicalText\": \"身能相能，如是者王，身不能，知恐懼而求能者，如是者彊；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 3,\n      \"canonicalText\": \"身不能，不知恐懼而求能者，安唯便僻左右親比己者之用，如是者危削；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 4,\n      \"canonicalText\": \"綦之而亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 5,\n      \"canonicalText\": \"國者，巨用之則大，小用之則小；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 6,\n      \"canonicalText\": \"綦大而王，綦小而亡，小巨分流者存。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 7,\n      \"canonicalText\": \"巨用之者，先義而後利，安不卹親疏，不卹貴賤，唯誠能之求，夫是之謂巨用之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 8,\n      \"canonicalText\": \"小用之者，先利而後義，安不卹是非，不治曲直，唯便僻親比己者之用，夫是之謂小用之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 9,\n      \"canonicalText\": \"巨用之者若彼，小用之者若此，小巨分流者，亦一若彼，一若此也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 10,\n      \"canonicalText\": \"故曰：「粹而王，駁而霸，無一焉而亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-8_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-8\",\n      \"order\": 11,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-9_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-9\",\n      \"order\": 1,\n      \"canonicalText\": \"國無禮則不正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-9_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-9\",\n      \"order\": 2,\n      \"canonicalText\": \"禮之所以正國也，譬之：猶衡之於輕重也，猶繩墨之於曲直也，猶規矩之於方圓也，既錯之而人莫之能誣也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-9_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-9\",\n      \"order\": 3,\n      \"canonicalText\": \"《詩》雲：「如霜雪之將將，如日月之光明，為之則存，不為則亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-9_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-9\",\n      \"order\": 4,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 1,\n      \"canonicalText\": \"國危則無樂君，國安則無憂民。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 2,\n      \"canonicalText\": \"亂則國危，治則國安。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 3,\n      \"canonicalText\": \"今君人者，急逐樂而緩治國，豈不過甚矣哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 4,\n      \"canonicalText\": \"譬之是由好聲色，而恬無耳目也，豈不哀哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 5,\n      \"canonicalText\": \"夫人之情，目欲綦色，耳欲綦聲，口欲綦味，鼻欲綦臭，心欲綦佚。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 6,\n      \"canonicalText\": \"此五綦者，人情之所必不免也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 7,\n      \"canonicalText\": \"養五綦者有具。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 8,\n      \"canonicalText\": \"無其具，則五綦者不可得而致也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 9,\n      \"canonicalText\": \"萬乘之國，可謂廣大富厚矣，加有治辨彊固之道焉，若是則恬愉無患難矣，然後養五綦之具具也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 10,\n      \"canonicalText\": \"故百樂者，生於治國者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 11,\n      \"canonicalText\": \"憂患者，生於亂國者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 12,\n      \"canonicalText\": \"急逐樂而緩治國者，非知樂者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 13,\n      \"canonicalText\": \"故明君者，必將先治其國，然後百樂得其中。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 14,\n      \"canonicalText\": \"闇君者，必將急逐樂而緩治國，故憂患不可勝校也，必至於身死國亡然後止也，豈不哀哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 15,\n      \"canonicalText\": \"將以為樂，乃得憂焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 16,\n      \"canonicalText\": \"將以為安，乃得危焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 17,\n      \"canonicalText\": \"將以為福，乃得死亡焉，豈不哀哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 18,\n      \"canonicalText\": \"於乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 19,\n      \"canonicalText\": \"君人者，亦可以察若言矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 20,\n      \"canonicalText\": \"故治國有道，人主有職。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 21,\n      \"canonicalText\": \"若夫貫日而治詳，一日而曲列之，是所使夫百吏官人為也，不足以是傷遊玩安燕之樂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 22,\n      \"canonicalText\": \"若夫論一相以兼率之，使臣下百吏莫不宿道鄉方而務，是夫人主之職也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-23\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 23,\n      \"canonicalText\": \"若是則一天下，名配堯禹。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-24\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 24,\n      \"canonicalText\": \"之主者，守至約而詳，事至佚而功，垂衣裳，不下簟席之上，而海內之人莫不願得以為帝王。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-10_s-25\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-10\",\n      \"order\": 25,\n      \"canonicalText\": \"夫是之謂至約，樂莫大焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 1,\n      \"canonicalText\": \"人主者，以官人為能者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 2,\n      \"canonicalText\": \"匹夫者，以自能為能者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 3,\n      \"canonicalText\": \"人主得使人為之，匹夫則無所移之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 4,\n      \"canonicalText\": \"百畝一守，事業窮，無所移之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 5,\n      \"canonicalText\": \"今以一人兼聽天下，日有餘而治不足者，使人為之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 6,\n      \"canonicalText\": \"大有天下，小有一國，必自為之然後可，則勞苦秏顇莫甚焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 7,\n      \"canonicalText\": \"如是，則雖臧獲不肯與天子易埶業。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 8,\n      \"canonicalText\": \"以是縣天下，一四海，何故必自為之？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 9,\n      \"canonicalText\": \"為之者，役夫之道也，墨子之說也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 10,\n      \"canonicalText\": \"論德使能而官施之者，聖王之道也，儒之所謹守也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 11,\n      \"canonicalText\": \"傳曰：農分田而耕，賈分貨而販，百工分事而勸，士大夫分職而聽，建國諸侯之君分土而守，三公摠方而議，則天子共己而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-11_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-11\",\n      \"order\": 12,\n      \"canonicalText\": \"出若入若，天下莫不平均，莫不治辨，是百王之所同也，而禮法之大分也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 1,\n      \"canonicalText\": \"百里之地，可以取天下。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 2,\n      \"canonicalText\": \"是不虛；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 3,\n      \"canonicalText\": \"其難者在於人主之知之也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 4,\n      \"canonicalText\": \"取天下者，非負其土地而從之之謂也，道足以壹人而已矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 5,\n      \"canonicalText\": \"彼其人苟壹，則其土地奚去我而適它？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 6,\n      \"canonicalText\": \"故百里之地，其等位爵服，足以容天下之賢士矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 7,\n      \"canonicalText\": \"其官職事業，足以容天下之能士矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 8,\n      \"canonicalText\": \"循其舊法，擇其善者而明用之，足以順服好利之人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 9,\n      \"canonicalText\": \"賢士一焉，能士官焉，好利之人服焉，三者具而天下盡，無有是其外矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 10,\n      \"canonicalText\": \"故百里之地，足以竭埶矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 11,\n      \"canonicalText\": \"致忠信，箸仁義，足以竭人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 12,\n      \"canonicalText\": \"兩者合而天下取，諸侯後同者先危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 13,\n      \"canonicalText\": \"《詩》曰：「自西自東，自南自北，無思不服。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-12_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-12\",\n      \"order\": 14,\n      \"canonicalText\": \"」一人之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 1,\n      \"canonicalText\": \"羿、蜂門者，善服射者也；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 2,\n      \"canonicalText\": \"王良、造父者，善服馭者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 3,\n      \"canonicalText\": \"聰明君子者，善服人者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 4,\n      \"canonicalText\": \"人服而埶從之，人不服而埶去之，故王者已於服人矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 5,\n      \"canonicalText\": \"故人主欲得善射，射遠中微，則莫若羿、蜂門矣；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 6,\n      \"canonicalText\": \"欲得善馭，及速致遠，則莫若王良、造父矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 7,\n      \"canonicalText\": \"欲得調壹天下，制秦楚，則莫若聰明君子矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 8,\n      \"canonicalText\": \"其用知甚簡，其為事不勞，而功名致大，甚易處而極可樂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 9,\n      \"canonicalText\": \"故明君以為寶，而愚者以為難。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 10,\n      \"canonicalText\": \"夫貴為天子，富有天下，名為聖王，兼制人，人莫得而制也，是人情之所同欲也，而王者兼而有是者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 11,\n      \"canonicalText\": \"重色而衣之，重味而食之，重財物而制之，合天下而君之，飲食甚厚，聲樂甚大，臺謝甚高，園囿甚廣，臣使諸侯，一天下，是又人情之所同欲也，而天子之禮制如是者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 12,\n      \"canonicalText\": \"制度以陳，政令以挾，官人失要則死，公侯失禮則幽，四方之國，有侈離之德則必滅，名聲若日月，功績如天地，天下之人應之如景嚮，是又人情之所同欲也，而王者兼而有是者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 13,\n      \"canonicalText\": \"故人之情，口好味，而臭味莫美焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 14,\n      \"canonicalText\": \"耳好聲，而聲樂莫大焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 15,\n      \"canonicalText\": \"目好色，而文章致繁，婦女莫眾焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 16,\n      \"canonicalText\": \"形體好佚，而安重閒靜莫愉焉；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 17,\n      \"canonicalText\": \"心好利，而穀祿莫厚焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 18,\n      \"canonicalText\": \"合天下之所同願兼而有之，睪牢天下而制之若制子孫，人苟不狂惑戇陋者，其誰能睹是而不樂也哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 19,\n      \"canonicalText\": \"欲是之主，並肩而存；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 20,\n      \"canonicalText\": \"能建是之士，不世絕；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 21,\n      \"canonicalText\": \"千歲而不合，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 22,\n      \"canonicalText\": \"曰：人主不公，人臣不忠也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-23\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 23,\n      \"canonicalText\": \"人主則外賢而偏舉，人臣則爭職而妒賢，是其所以不合之故也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-24\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 24,\n      \"canonicalText\": \"人主胡不廣焉，無卹親疏，無偏貴賤，惟誠能之求？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-25\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 25,\n      \"canonicalText\": \"若是，則人臣輕職業讓賢，而安隨其後。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-26\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 26,\n      \"canonicalText\": \"如是，則舜禹還至，王業還起；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-27\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 27,\n      \"canonicalText\": \"功壹天下，名配舜禹，物由有可樂，如是其美焉者乎！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-28\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 28,\n      \"canonicalText\": \"嗚呼！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-29\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 29,\n      \"canonicalText\": \"君人者，亦可以察若言矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-30\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 30,\n      \"canonicalText\": \"楊朱哭衢塗，曰：「此夫過舉蹞步，而覺跌千里者夫！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-31\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 31,\n      \"canonicalText\": \"」哀哭之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-32\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 32,\n      \"canonicalText\": \"此亦榮辱、安危、存亡之衢已，此其為可哀，甚於衢塗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-33\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 33,\n      \"canonicalText\": \"嗚呼！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-34\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 34,\n      \"canonicalText\": \"哀哉！\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-13_s-35\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-13\",\n      \"order\": 35,\n      \"canonicalText\": \"君人者，千歲而不覺也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 1,\n      \"canonicalText\": \"無國而不有治法，無國而不有亂法；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 2,\n      \"canonicalText\": \"無國而不有賢士，無國而不有罷士；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 3,\n      \"canonicalText\": \"無國而不有願民，無國而不有悍民；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 4,\n      \"canonicalText\": \"無國而不有美俗，無國而不有惡俗。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 5,\n      \"canonicalText\": \"兩者並行而國在，上偏而國安，在下偏而國危；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 6,\n      \"canonicalText\": \"上一而王，下一而亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 7,\n      \"canonicalText\": \"故其法治，其佐賢，其民願，其俗美，而四者齊，夫是之謂上一。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 8,\n      \"canonicalText\": \"如是則不戰而勝，不攻而得，甲兵不勞而天下服。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 9,\n      \"canonicalText\": \"故湯以亳，文王以鄗，皆百里之地也，天下為一，諸侯為臣，通達之屬，莫不從服，無它故焉，四者齊也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 10,\n      \"canonicalText\": \"桀紂即厚於有天下之埶，索為匹夫而不可得也，是無它故焉，四者並亡也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-14_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-14\",\n      \"order\": 11,\n      \"canonicalText\": \"故百王之法不同，若是所歸者一也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 1,\n      \"canonicalText\": \"上莫不致愛其下，而制之以禮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 2,\n      \"canonicalText\": \"上之於下，如保赤子，政令制度，所以接下之人百姓，有不理者如豪末，則雖孤獨鰥寡必不加焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 3,\n      \"canonicalText\": \"故下之親上，歡如父母，可殺而不可使不順。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 4,\n      \"canonicalText\": \"君臣上下，貴賤長幼，至於庶人，莫不以是為隆正；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 5,\n      \"canonicalText\": \"然後皆內自省，以謹於分。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 6,\n      \"canonicalText\": \"是百王之所以同也，而禮法之樞要也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 7,\n      \"canonicalText\": \"然後農分田而耕，賈分貨而販，百工分事而勸，士大夫分職而聽，建國諸侯之君分土而守，三公總方而議，則天子共己而止矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 8,\n      \"canonicalText\": \"出若入若，天下莫不均平，莫不治辨。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 9,\n      \"canonicalText\": \"是百王之所同，而禮法之大分也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 10,\n      \"canonicalText\": \"若夫貫日而治平，權物而稱用，使衣服有制，宮室有度，人徒有數，喪祭械用皆有等宜，以是用挾於萬物，尺寸尋丈，莫得不循乎制度數量然後行，則是官人使吏之事也，不足數於大君子之前。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 11,\n      \"canonicalText\": \"故君人者，立隆政本朝而當，所使要百事者誠仁人也，則身佚而國治，功大而名美，上可以王，下可以霸。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 12,\n      \"canonicalText\": \"立隆正本朝而不當，所使要百事者非仁人也，則身勞而國亂，功廢而名辱，社稷必危，是人君者之樞機也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 13,\n      \"canonicalText\": \"故能當一人而天下取，失當一人而社稷危。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 14,\n      \"canonicalText\": \"不能當一人，而能當千百人者，說無之有也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 15,\n      \"canonicalText\": \"既能當一人，則身有何勞而為？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 16,\n      \"canonicalText\": \"垂衣裳而天下定。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 17,\n      \"canonicalText\": \"故湯用伊尹，文王用呂尚，武王用召公，成王用周公旦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-18\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 18,\n      \"canonicalText\": \"卑者五伯，齊桓公閨門之內，縣樂、奢泰、遊抏之脩，於天下不見謂脩，然九合諸侯，一匡天下，為五伯長，是亦無他故焉，知一政於管仲也，是君人者之要守也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-19\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 19,\n      \"canonicalText\": \"知者易為之興力，而功名綦大。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-20\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 20,\n      \"canonicalText\": \"舍是而孰足為也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-21\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 21,\n      \"canonicalText\": \"故古之人，有大功名者，必道是者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-22\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 22,\n      \"canonicalText\": \"喪其國危其身者，必反是者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-23\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 23,\n      \"canonicalText\": \"故孔子曰：「知者之知，固以多矣，有以守少，能無察乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-24\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 24,\n      \"canonicalText\": \"愚者之知，固以少矣，有以守多，能無狂乎？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-15_s-25\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-15\",\n      \"order\": 25,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-16_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-16\",\n      \"order\": 1,\n      \"canonicalText\": \"治國者分已定，則主相臣下百吏，各謹其所聞，不務聽其所不聞；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-16_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-16\",\n      \"order\": 2,\n      \"canonicalText\": \"各謹其所見，不務視其所不見。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-16_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-16\",\n      \"order\": 3,\n      \"canonicalText\": \"所聞所見誠以齊矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-16_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-16\",\n      \"order\": 4,\n      \"canonicalText\": \"則雖幽閒隱闢，百姓莫敢不敬分安制，以化其上，是治國之徵也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 1,\n      \"canonicalText\": \"主道治近不治遠，治明不治幽，治一不治二。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 2,\n      \"canonicalText\": \"主能治近則遠者理，主能治明則幽者化，主能當一則百事正。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 3,\n      \"canonicalText\": \"夫兼聽天下，日有餘而治不足者，如此也，是治之極也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 4,\n      \"canonicalText\": \"既能治近，又務治遠；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 5,\n      \"canonicalText\": \"既能治明，又務見幽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 6,\n      \"canonicalText\": \"既能當一，又務正百，是過者也，過猶不及也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 7,\n      \"canonicalText\": \"闢之是猶立直木而求其影之枉也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 8,\n      \"canonicalText\": \"不能治近，又務治遠；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 9,\n      \"canonicalText\": \"不能察明，又務見幽；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 10,\n      \"canonicalText\": \"不能當一，又務正百，是悖者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 11,\n      \"canonicalText\": \"闢之是猶立枉木而求其影之直也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 12,\n      \"canonicalText\": \"故明主好要，而闇主好詳；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-13\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 13,\n      \"canonicalText\": \"主好要則百事詳，主好詳則百事荒。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-14\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 14,\n      \"canonicalText\": \"君者、論一相，陳一法，明一指，以兼覆之，兼炤之，以觀其盛者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-15\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 15,\n      \"canonicalText\": \"相者，論列百官之長，要百事之聽，以飾朝廷臣下百吏之分，度其功勞，論其慶賞，歲終奉其成功以效於君。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-16\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 16,\n      \"canonicalText\": \"當則可，不當則廢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-17_s-17\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-17\",\n      \"order\": 17,\n      \"canonicalText\": \"故君人勞於索之，而休於使之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 1,\n      \"canonicalText\": \"用國者，得百姓之力者富，得百姓之死者彊，得百姓之譽者榮。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 2,\n      \"canonicalText\": \"三得者具而天下歸之，三得者亡而天下去之；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 3,\n      \"canonicalText\": \"天下歸之之謂王，天下去之之謂亡。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 4,\n      \"canonicalText\": \"湯武者，脩其道，行其義，興天下同利，除天下同害，天下歸之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 5,\n      \"canonicalText\": \"故厚德音以先之，明禮義以道之，致忠信以愛之，賞賢使能以次之，爵服賞慶以申重之，時其事，輕其任，以調齊之，潢然兼覆之，養長之，如保赤子。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 6,\n      \"canonicalText\": \"生民則致寬，使民則綦理，辯政令制度，所以接天下之人百姓，有非理者如豪末，則雖孤獨鰥寡，必不加焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 7,\n      \"canonicalText\": \"是故百姓貴之如帝，親之如父母，為之出死斷亡而不愉者，無它故焉，道德誠明，利澤誠厚也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 8,\n      \"canonicalText\": \"亂世不然，汙漫突盜以先之，權謀傾覆以示之，俳優、侏儒、婦女之請謁以悖之，使愚詔知，使不肖臨賢，生民則致貧隘，使民則極勞苦。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 9,\n      \"canonicalText\": \"是故，百姓賤之如尪，惡之如鬼，日欲司閒而相與投藉之，去逐之。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 10,\n      \"canonicalText\": \"卒有寇難之事，又望百姓之為己死，不可得也，說無以取之焉。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 11,\n      \"canonicalText\": \"孔子曰：「審吾所以適人，適人之所以來我也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-18_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-18\",\n      \"order\": 12,\n      \"canonicalText\": \"」此之謂也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 1,\n      \"canonicalText\": \"傷國者，何也？\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 2,\n      \"canonicalText\": \"曰：以小人尚民而威，以非所取於民而巧，是傷國之大災也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 3,\n      \"canonicalText\": \"大國之主也，而好見小利，是傷國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 4,\n      \"canonicalText\": \"其於聲色、臺榭、園囿也，愈厭而好新，是傷國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 5,\n      \"canonicalText\": \"不好脩正其所以有，啖啖常欲人之有，是傷國。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 6,\n      \"canonicalText\": \"三邪者在匈中，而又好以權謀傾覆之人，斷事其外，若是，則權輕名辱，社稷必危，是傷國者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 7,\n      \"canonicalText\": \"大國之主也，不隆本行，不敬舊法，而好詐故，若是，則夫朝廷群臣，亦從而成俗於不隆禮義而好傾覆也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 8,\n      \"canonicalText\": \"朝廷群臣之俗若是，則夫眾庶百姓亦從而成俗於不隆禮義而好貪利矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 9,\n      \"canonicalText\": \"君臣上下之俗，莫不若是，則地雖廣，權必輕；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 10,\n      \"canonicalText\": \"人雖眾，兵必弱；\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 11,\n      \"canonicalText\": \"刑罰雖繁，令不下通。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-19_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-19\",\n      \"order\": 12,\n      \"canonicalText\": \"夫是之謂危國，是傷國者也。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-1\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 1,\n      \"canonicalText\": \"儒者為之不然，必將曲辨：朝廷必將隆禮義而審貴賤，若是、則士大夫莫不敬節死制者矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-2\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 2,\n      \"canonicalText\": \"百官則將齊其制度，重其官秩，若是、則百吏莫不畏法而遵繩矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-3\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 3,\n      \"canonicalText\": \"關市幾而不徵，質律禁止而不偏，如是、則商賈莫不敦愨而無詐矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-4\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 4,\n      \"canonicalText\": \"百工將時斬伐，佻其期日，而利其巧任，如是，則百工莫不忠信而不楛矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-5\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 5,\n      \"canonicalText\": \"縣鄙則將輕田野之稅，省刀布之歛，罕舉力役，無奪農時，如是、農夫莫不樸力而寡能矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-6\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 6,\n      \"canonicalText\": \"士大夫務節死制，然而兵勁。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-7\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 7,\n      \"canonicalText\": \"百吏畏法循繩，然後國常不亂。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-8\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 8,\n      \"canonicalText\": \"商賈敦愨無詐，則商旅安，貨通財，而國求給矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-9\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 9,\n      \"canonicalText\": \"百工忠信而不楛，則器用巧便而財不匱矣。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-10\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 10,\n      \"canonicalText\": \"農夫樸力而寡能，則上不失天時，下不失地利，中得人和，而百事不廢。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-11\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 11,\n      \"canonicalText\": \"是之謂政令行，風俗美，以守則固，以徵則彊，居則有名，動則有功。\",\n      \"chunks\": [],\n      \"tags\": []\n    },\n    {\n      \"id\": \"xunzi_ch-11_p-20_s-12\",\n      \"workId\": \"xunzi\",\n      \"chapterId\": \"xunzi_ch-11\",\n      \"passageId\": \"xunzi_ch-11_p-20\",\n      \"order\": 12,\n      \"canonicalText\": \"此儒之所謂曲辨也。\",\n      \"chunks\": [],\n      \"tags\": []\n    }\n  ]\n}"
) as ChapterBundle
